begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('1f000000-0000-0000-0000-000000000001');
insert into public.members(id,auth_user_id,username,full_name_en,system_role) values ('2f000000-0000-0000-0000-000000000001','1f000000-0000-0000-0000-000000000001','edit_user_1','Edit user 1','OWNER');
insert into auth.users(id) values ('1f000000-0000-0000-0000-000000000002');
insert into public.members(id,auth_user_id,username,full_name_en,system_role) values ('2f000000-0000-0000-0000-000000000002','1f000000-0000-0000-0000-000000000002','edit_user_2','Edit user 2','MEMBER');
insert into auth.users(id) values ('1f000000-0000-0000-0000-000000000003');
insert into public.members(id,auth_user_id,username,full_name_en,system_role) values ('2f000000-0000-0000-0000-000000000003','1f000000-0000-0000-0000-000000000003','edit_user_3','Edit user 3','MEMBER');
insert into auth.users(id) values ('1f000000-0000-0000-0000-000000000004');
insert into public.members(id,auth_user_id,username,full_name_en,system_role) values ('2f000000-0000-0000-0000-000000000004','1f000000-0000-0000-0000-000000000004','edit_user_4','Edit user 4','MEMBER');
insert into public.events(id,code,name_en,event_bonus_cap,event_penalty_cap,match_bonus_cap,match_penalty_cap,leaderboard_public) values ('3f000000-0000-0000-0000-000000000001','EDIT','Edit event',2,1,2,1,true),('3f000000-0000-0000-0000-000000000002','OTHER','Other event',2,1,2,1,true);
insert into public.teams(id,event_id,code,name_en,avatar_key,color_hex) values ('4f000000-0000-0000-0000-000000000001','3f000000-0000-0000-0000-000000000001','T01','Team 1','falcon','#123456'),('4f000000-0000-0000-0000-000000000002','3f000000-0000-0000-0000-000000000001','T02','Team 2','lion','#654321');
insert into public.games(id,event_id,code,name_en) values ('5f000000-0000-0000-0000-000000000001','3f000000-0000-0000-0000-000000000001','G01','Game');
insert into public.rounds(id,event_id,number,status,duration_min,started_at) values ('6f000000-0000-0000-0000-000000000001','3f000000-0000-0000-0000-000000000001',1,'CLOSED',15,now()-interval '1 hour');
insert into public.matches(id,event_id,round_id,game_id) values ('7f000000-0000-0000-0000-000000000001','3f000000-0000-0000-0000-000000000001','6f000000-0000-0000-0000-000000000001','5f000000-0000-0000-0000-000000000001');
insert into public.match_participants(match_id,round_id,team_id,side) values ('7f000000-0000-0000-0000-000000000001','6f000000-0000-0000-0000-000000000001','4f000000-0000-0000-0000-000000000001','A'),('7f000000-0000-0000-0000-000000000001','6f000000-0000-0000-0000-000000000001','4f000000-0000-0000-0000-000000000002','B');
insert into public.event_roles(event_id,member_id,role) values ('3f000000-0000-0000-0000-000000000001','2f000000-0000-0000-0000-000000000002','REFEREE'),('3f000000-0000-0000-0000-000000000001','2f000000-0000-0000-0000-000000000003','EVENT_ADMIN'),('3f000000-0000-0000-0000-000000000002','2f000000-0000-0000-0000-000000000004','EVENT_ADMIN'),('3f000000-0000-0000-0000-000000000001','2f000000-0000-0000-0000-000000000004','REFEREE');
insert into public.referee_games(event_id,member_id,game_id) values ('3f000000-0000-0000-0000-000000000001','2f000000-0000-0000-0000-000000000002','5f000000-0000-0000-0000-000000000001'),('3f000000-0000-0000-0000-000000000001','2f000000-0000-0000-0000-000000000004','5f000000-0000-0000-0000-000000000001');
insert into public.adjustments(id,event_id,scope,match_id,team_id,points,reason,given_by) values
('8f000000-0000-0000-0000-000000000001','3f000000-0000-0000-0000-000000000001','MATCH','7f000000-0000-0000-0000-000000000001','4f000000-0000-0000-0000-000000000001',1,'Original bonus','2f000000-0000-0000-0000-000000000002'),
('8f000000-0000-0000-0000-000000000002','3f000000-0000-0000-0000-000000000001','MATCH','7f000000-0000-0000-0000-000000000001','4f000000-0000-0000-0000-000000000001',1,'Other bonus','2f000000-0000-0000-0000-000000000003'),
('8f000000-0000-0000-0000-000000000003','3f000000-0000-0000-0000-000000000001','EVENT',null,'4f000000-0000-0000-0000-000000000001',1,'Event bonus','2f000000-0000-0000-0000-000000000002');
create temp table edit_original as select * from public.adjustments where id='8f000000-0000-0000-0000-000000000001';
select ok(not has_table_privilege('authenticated','public.adjustment_revisions','UPDATE'),'history cannot be overwritten by staff');
select ok(not has_table_privilege('anon','public.adjustment_revisions','SELECT'),'history table is not directly public');
select ok(not has_function_privilege('anon','public.edit_adjustment(uuid,uuid,numeric,text,integer)','EXECUTE'),'anonymous cannot edit bonuses');
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.25,'Unknown member',0)$$,'P0001','FORBIDDEN','missing active member cannot edit');
select throws_ok($$select public.revoke_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001','Unknown member')$$,'P0001','FORBIDDEN','missing active member cannot revoke');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000004',true);
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.25,'Correct amount',0)$$,'P0001','FORBIDDEN','other referee and other-event moderator cannot edit another issuer bonus');
select throws_ok($$select public.revoke_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001','Not allowed')$$,'P0001','FORBIDDEN','other referee cannot revoke another issuer bonus');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000002',true);
select is((public.edit_adjustment('9f000000-0000-0000-0000-000000000001','8f000000-0000-0000-0000-000000000001',.25,'Correct amount',0)->>'points')::numeric,.25::numeric,'original issuer adjusts to quarter heart after round closes');
select is((public.edit_adjustment('9f000000-0000-0000-0000-000000000001','8f000000-0000-0000-0000-000000000001',.25,'Correct amount',0)->>'revision')::int,1,'same operation replay returns revision one');
select is((select (x->>'points')::numeric from jsonb_array_elements(public.get_match_entry('7f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),.25::numeric,'same adjustment ID now displays its current amount');
select is((select jsonb_array_length(x->'history') from jsonb_array_elements(public.get_match_entry('7f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),1,'replay creates exactly one history record');
select is((select (x->'history'->0->>'old_points')::numeric from jsonb_array_elements(public.get_match_entry('7f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),1::numeric,'history retains the originally granted amount');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.5,'Correct amount',0)$$,'P0001','ADJUSTMENT_CHANGED','stale editor cannot overwrite a newer correction');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',1.01,'Correct amount',1)$$,'P0001','CAP_EXCEEDED','replacement plus another bonus cannot exceed the cap');
select lives_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',1,'Correct amount',1)$$,'replacement excludes its own old amount when consuming the cap');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',0,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','invalid new amount 0 is rejected');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.001,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','invalid new amount .001 is rejected');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001','NaN'::numeric,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','invalid new amount NaN::numeric is rejected');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001','Infinity'::numeric,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','invalid new amount Infinity::numeric is rejected');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',2147483648,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','invalid new amount 2147483648 is rejected');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.5,'x',2)$$,'P0001','INVALID_REASON','every correction needs a useful reason');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',1,'Correct amount',2)$$,'P0001','INVALID_ADJUSTMENT','no-op edit does not append history');
select lives_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',-.5,'Correct amount',2)$$,'signed correction uses the separate penalty cap');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',-1.01,'Correct amount',3)$$,'P0001','CAP_EXCEEDED','negative replacement also enforces caps');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000003',true);
select lives_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.5,'Correct amount',3)$$,'event moderator can correct someone elses bonus');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.25,'Correct amount',4)$$,'app owner can correct someone elses bonus');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000002',true);
select is((public.edit_adjustment('9f000000-0000-0000-0000-000000000001','8f000000-0000-0000-0000-000000000001',.25,'Correct amount',0)->>'revision')::int,1,'old replay returns original receipt after later edits');
select is((select (x->>'revision')::int from jsonb_array_elements(public.get_match_entry('7f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),5,'old replay does not undo later corrections');
select lives_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000003',.5,'Correct amount',0)$$,'original issuer can edit own event-scoped bonus');
select lives_ok($$select public.revoke_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001','Cancel corrected bonus')$$,'original issuer can revoke after correction and closure');
select throws_ok($$select public.edit_adjustment(gen_random_uuid(),'8f000000-0000-0000-0000-000000000001',.5,'Correct amount',5)$$,'P0001','ADJUSTMENT_REVOKED','revoked adjustment cannot be edited');
select is((select jsonb_array_length(x->'history') from jsonb_array_elements(public.get_match_entry('7f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),5,'revocation preserves all corrections');
reset role;
select is((select count(*) from public.adjustments where id='8f000000-0000-0000-0000-000000000001'),1::bigint,'editing never replaces or duplicates the original bonus');
select is((select (a.given_by,a.created_at,a.reason,a.team_id,a.scope,a.match_id)=(o.given_by,o.created_at,o.reason,o.team_id,o.scope,o.match_id) from public.adjustments a cross join edit_original o where a.id=o.id),true,'original issuer date reason team and scope are preserved');
select is((select count(*) from public.adjustment_revisions where adjustment_id='8f000000-0000-0000-0000-000000000001'),5::bigint,'failed edits leave no history fragments');
select set_config('request.jwt.claim.sub','1f000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is((select jsonb_array_length(x->'history') from jsonb_array_elements(public.get_export_data('3f000000-0000-0000-0000-000000000001')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000001'),5,'export payload preserves complete history');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select is((select (x->>'points')::numeric from jsonb_array_elements(public.get_team_view('3f000000-0000-0000-0000-000000000001','T01')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000003'),.5::numeric,'public current amount reflects the edit');
select is((select x ? 'history' from jsonb_array_elements(public.get_team_view('3f000000-0000-0000-0000-000000000001','T01')->'adjustments') x where x->>'id'='8f000000-0000-0000-0000-000000000003'),false,'staff correction notes are not added to public reads');
reset role;
select * from finish();
rollback;
